-- Message content: one language per campaign, generated by a queue job.
ALTER TABLE campaigns
    ADD COLUMN language        text  CHECK (language IN ('tr', 'en')),
    ADD COLUMN sms_body        text  NOT NULL DEFAULT '',
    ADD COLUMN email_subject   text  NOT NULL DEFAULT '',
    ADD COLUMN email_body      text  NOT NULL DEFAULT '',
    -- none: never generated; generating: a job is running; ready: valid for the
    -- current audience; failed: generation failed; invalid: the audience changed
    -- and the messages no longer fit it.
    ADD COLUMN content_state   text  NOT NULL DEFAULT 'none'
                               CHECK (content_state IN ('none', 'generating', 'ready', 'failed', 'invalid')),
    -- Bumped by every generation request and hand edit; a job only saves its
    -- result if the version is still its own, so the newest request wins.
    ADD COLUMN content_version int   NOT NULL DEFAULT 0,
    ADD COLUMN content_error   jsonb,
    ADD COLUMN content_check   jsonb;
